 'g2-science-t1':[['Which one is living?',['a tree','a rock','a chair','a car'],'A <b class="exa">tree</b> grows and needs water.'],['Which one is non-living?',['a pencil','a cat','a flower','a bird'],'A <b class="exa">pencil</b> does not grow or breathe.'],['All living things need…',['food and water','toys','batteries','paint'],'Living things need <b class="exa">food and water</b>.'],['Which can grow?',['a puppy','a ball','a spoon','a shoe'],'A <b class="exa">puppy</b> grows into a dog.'],['Do plants breathe?',['yes','no','only at night','only in water'],'<b class="exa">Yes</b>, plants take in air too.']],
 'g2-science-t2':[['Which part of the plant takes in water?',['roots','flowers','fruit','seeds'],'The <b class="exa">roots</b> take in water.'],['Which part carries water up the plant?',['stem','leaf','flower','seed'],'The <b class="exa">stem</b> carries water up.'],['Where does a plant make its food?',['leaves','roots','soil','seeds'],'Plants make food in their <b class="exa">leaves</b>.'],['What grows from a seed?',['a new plant','a stone','a cloud','an animal'],'A seed grows into <b class="exa">a new plant</b>.'],['Plants give us…',['oxygen','plastic','metal','glass'],'Plants give us <b class="exa">oxygen</b> to breathe.']],
 'g2-science-t3':[['Where does a camel live?',['desert','sea','forest','snow'],'Camels live in the <b class="exa">desert</b>.'],['Where does a polar bear live?',['icy land','desert','pond','jungle'],'Polar bears live on <b class="exa">icy land</b>.'],['Where does a fish live?',['water','tree','burrow','nest'],'Fish live in <b class="exa">water</b>.'],['A bird\'s home is a…',['nest','den','hive','burrow'],'A bird lives in a <b class="exa">nest</b>.'],['Bees live in a…',['hive','nest','cave','stable'],'Bees live in a <b class="exa">hive</b>.'],['Which animal lives in the Thar desert?',['camel','penguin','whale','polar bear'],'The <b class="exa">camel</b> lives in the Thar.']],
 'g2-history-t1':[['Early people lived in…',['caves','flats','hotels','offices'],'Early people lived in <b class="exa">caves</b>.'],['How did early people get food?',['hunting and gathering','shopping','delivery','restaurants'],'They got food by <b class="exa">hunting and gathering</b>.'],['Early people made tools from…',['stone','plastic','steel','glass'],'Early tools were made of <b class="exa">stone</b>.'],['What did early people discover that kept them warm?',['fire','electricity','gas heaters','blankets'],'They discovered <b class="exa">fire</b>.'],['Where did early people draw pictures?',['on cave walls','on paper','on phones','on whiteboards'],'They painted <b class="exa">on cave walls</b>.']],
 'g2-history-t2':[['The Indus Valley people lived near which river?',['Indus','Nile','Thames','Amazon'],'They lived near the <b class="exa">Indus</b> river.'],['Which famous Indus Valley city is in Sindh?',['Mohenjo-daro','Lahore','Islamabad','Quetta'],'<b class="exa">Mohenjo-daro</b> is in Sindh.'],['Which Indus city is in Punjab?',['Harappa','Karachi','Gwadar','Swat'],'<b class="exa">Harappa</b> is in Punjab.'],['Indus Valley houses were made of…',['baked bricks','glass','wood only','plastic'],'They built with <b class="exa">baked bricks</b>.'],['The Indus people were famous for clean…',['drains','cars','trains','phones'],'They had covered <b class="exa">drains</b>.']],
 'g2-history-t3':[['Ancient Egypt grew along which river?',['Nile','Indus','Ravi','Ganges'],'Egypt grew along the <b class="exa">Nile</b>.'],['Egyptian kings were called…',['pharaohs','sultans','emperors','presidents'],'Kings were called <b class="exa">pharaohs</b>.'],['The pyramids were built as…',['tombs','schools','markets','farms'],'Pyramids were <b class="exa">tombs</b>.'],['Egyptian picture writing is called…',['hieroglyphs','Urdu','English','emoji'],'It is called <b class="exa">hieroglyphs</b>.'],['Egypt is in which continent?',['Africa','Asia','Europe','Australia'],'Egypt is in <b class="exa">Africa</b>.']],
 'g2-geography-t1':[['The sun rises in the…',['east','west','north','south'],'The sun rises in the <b class="exa">east</b>.'],['The sun sets in the…',['west','east','north','south'],'The sun sets in the <b class="exa">west</b>.'],['On a map, north is usually at the…',['top','bottom','left','right'],'North is at the <b class="exa">top</b>.'],['What shows directions on a map?',['a compass rose','a scale','a key','a title'],'A <b class="exa">compass rose</b> shows directions.'],['A map\'s key tells us…',['what the symbols mean','the time','the weather','the date'],'The key explains <b class="exa">what the symbols mean</b>.']],
 'g2-geography-t2':[['How many continents are there?',['7','5','6','8'],'There are <b class="exa">7</b> continents.'],['Pakistan is in which continent?',['Asia','Africa','Europe','Australia'],'Pakistan is in <b class="exa">Asia</b>.'],['Which is the biggest ocean?',['Pacific','Indian','Atlantic','Arctic'],'The <b class="exa">Pacific</b> is the biggest ocean.'],['Which ocean is south of Pakistan?',['Indian','Pacific','Arctic','Atlantic'],'The <b class="exa">Indian</b> Ocean (Arabian Sea) is to the south.'],['Which is the coldest continent?',['Antarctica','Asia','Africa','Europe'],'<b class="exa">Antarctica</b> is the coldest.']],
 'g2-geography-t3':[['How many provinces does Pakistan have?',['4','5','3','6'],'Pakistan has <b class="exa">4</b> provinces.'],['Lahore is the capital of…',['Punjab','Sindh','Balochistan','Khyber Pakhtunkhwa'],'Lahore is the capital of <b class="exa">Punjab</b>.'],['Karachi is the capital of…',['Sindh','Punjab','Balochistan','Khyber Pakhtunkhwa'],'Karachi is the capital of <b class="exa">Sindh</b>.'],['Quetta is the capital of…',['Balochistan','Sindh','Punjab','Khyber Pakhtunkhwa'],'Quetta is the capital of <b class="exa">Balochistan</b>.'],['Peshawar is the capital of…',['Khyber Pakhtunkhwa','Punjab','Sindh','Balochistan'],'Peshawar is the capital of <b class="exa">Khyber Pakhtunkhwa</b>.'],['The biggest province by area is…',['Balochistan','Punjab','Sindh','Khyber Pakhtunkhwa'],'<b class="exa">Balochistan</b> is the biggest by area.']],
