 'g2-urdu-t3':[['"دن" کا الٹ؟',['رات','صبح','شام','دوپہر'],'دن کا الٹ <b class="exa">رات</b>'],['"گرم" کا الٹ؟',['ٹھنڈا','گیلا','بڑا','لمبا'],'گرم کا الٹ <b class="exa">ٹھنڈا</b>'],['"اوپر" کا الٹ؟',['نیچے','آگے','پیچھے','اندر'],'اوپر کا الٹ <b class="exa">نیچے</b>'],['"سچ" کا الٹ؟',['جھوٹ','صاف','اچھا','نیا'],'سچ کا الٹ <b class="exa">جھوٹ</b>'],['"امیر" کا الٹ؟',['غریب','بڑا','بوڑھا','موٹا'],'امیر کا الٹ <b class="exa">غریب</b>']],
 'g2-english-t1':[['Which word is an adverb?',['quickly','quick','quack','queen'],'<b class="exa">Quickly</b> tells how something is done.'],['Find the pronoun: "She is reading."',['She','is','reading','book'],'<b class="exa">She</b> takes the place of a name.'],['Which word is a preposition?',['under','apple','jump','happy'],'<b class="exa">Under</b> tells where.'],['"The cat sat ___ the mat."',['on','run','blue','cat'],'The cat sat <b class="exa">on</b> the mat.'],['Which word is a conjunction?',['and','table','sing','tall'],'<b class="exa">And</b> joins words or sentences.'],['Find the adjective: "The clever girl solved it."',['clever','girl','solved','it'],'<b class="exa">Clever</b> describes the girl.']],
 'g2-english-t2':[['un + happy = ?',['unhappy','happyun','inhappy','dishappy'],'un + happy = <b class="exa">unhappy</b>'],['re + play = ?',['replay','playre','unplay','preplay'],'re + play = <b class="exa">replay</b> (play again)'],['help + ful = ?',['helpful','helpfull','helpfil','fulhelp'],'help + ful = <b class="exa">helpful</b>'],['What does "un" mean in "unkind"?',['not','again','before','very'],'"un" means <b class="exa">not</b>.'],['care + less = ?',['careless','carless','carefulless','lesscare'],'care + less = <b class="exa">careless</b>'],['Which prefix means "again"?',['re','un','dis','pre'],'<b class="exa">re</b> means again.']],
 'g2-english-t3':[['A paragraph should start with a…',['topic sentence','full stop','question mark','title'],'Start with a <b class="exa">topic sentence</b>.'],['All sentences in a paragraph should be about…',['one main idea','many ideas','nothing','the weather'],'A paragraph is about <b class="exa">one main idea</b>.'],['The last sentence of a paragraph is the…',['concluding sentence','topic sentence','title','question'],'It ends with a <b class="exa">concluding sentence</b>.'],['Which sentence fits a paragraph about "My School"?',['Our school has a big playground.','I like mangoes.','The sea is blue.','My cat sleeps a lot.'],'<b class="exa">Our school has a big playground.</b> is about the school.'],['Which word joins two ideas?',['because','blue','table','run'],'<b class="exa">Because</b> joins ideas and gives a reason.']],
 'g3-english-t1':[['Which is a collective noun?',['flock','bird','fly','blue'],'A <b class="exa">flock</b> is a group of birds.'],['Which is an abstract noun?',['kindness','table','Karachi','team'],'You cannot touch <b class="exa">kindness</b>.'],['Which is a proper noun?',['Islamabad','city','river','crowd'],'<b class="exa">Islamabad</b> is a special name, so it starts with a capital.'],['a ___ of bees',['swarm','herd','bunch','school'],'A <b class="exa">swarm</b> of bees.'],['brave → ?',['bravery','braveness','braved','bravely'],'The noun from brave is <b class="exa">bravery</b>.'],['Which word names a feeling?',['joy','jump','jar','jolly'],'<b class="exa">Joy</b> is an abstract noun.']],
 'g3-english-t2':[['Past tense of "go"',['went','goed','gone','going'],'Yesterday I <b class="exa">went</b> home.'],['Past tense of "write"',['wrote','writed','written','writes'],'She <b class="exa">wrote</b> a letter.'],['"Look! The boys ___ football."',['are playing','plays','played','is playing'],'Happening now: <b class="exa">are playing</b>.'],['Which sentence is in the future?',['I will visit Nani.','I visited Nani.','I visit Nani.','I am visiting Nani.'],'<b class="exa">Will</b> shows the future.'],['"She ___ milk every morning."',['drinks','drank','drinking','drink'],'Every morning is a habit: <b class="exa">drinks</b>.'],['Past tense of "see"',['saw','seed','seen','sees'],'We <b class="exa">saw</b> a rainbow.']],
 'g3-english-t3':[['"Bilal ___ two sisters."',['has','have','having','haves'],'One person takes <b class="exa">has</b>.'],['"My parents ___ a shop."',['have','has','is','does'],'Two people take <b class="exa">have</b>.'],['"___ she like tea?"',['Does','Do','Is','Are'],'She takes <b class="exa">does</b>.'],['"Last night the stars ___ bright."',['were','was','are','is'],'Many stars, past time: <b class="exa">were</b>.'],['"Zara ___ the news." (watch)',['watches','watchs','watching','watch'],'Add -es after ch: <b class="exa">watches</b>.'],['"The bird ___ high." (fly)',['flies','flys','flyes','fly'],'y changes to ies: <b class="exa">flies</b>.']],
