/* number generators for maths topics: fresh numbers every load */
const rint=(a,b)=>a+Math.floor(Math.random()*(b-a+1));
function mathExtra(id){const g=[],mk=(q,a,exp,sub)=>g.push([q,[String(a),...near(a).map(String)],exp,sub]);
 const add=(lo,hi,k)=>{for(let i=0;i<k;i++){const x=rint(lo,hi),y=rint(lo,hi);mk(`${x} + ${y} = <span class="qbl"></span>`,x+y,`${x} + ${y} = <b class="exa">${x+y}</b>`,'Add the numbers.')}};
 const sub=(lo,hi,k)=>{for(let i=0;i<k;i++){const x=rint(lo,hi),y=rint(0,x);mk(`${x} − ${y} = <span class="qbl"></span>`,x-y,`${x} − ${y} = <b class="exa">${x-y}</b>`,'Take away.')}};
 const mul=(tab,k)=>{for(let i=0;i<k;i++){const t=pickOne(tab),y=rint(1,10);mk(`${t} × ${y} = <span class="qbl"></span>`,t*y,`${t} × ${y} = <b class="exa">${t*y}</b>`,'Multiply.')}};
 if(id==='maths-t1'||id==='kg-maths-t1'){for(let i=0;i<5;i++){const n=rint(1,19);mk(`Which number comes after ${n}?`,n+1,`After ${n} comes <b class="exa">${n+1}</b>.`,'Count on by one.')}}
 if(id==='nursery-maths-t1'||id==='nursery-maths-t2'){const [lo,hi]=id.endsWith('1')?[1,5]:[5,10];for(let i=0;i<4;i++){const x=rint(lo,hi);let y=rint(lo,hi);if(y===x)y=x===hi?x-1:x+1;g.push([`Which number is bigger: ${x} or ${y}?`,[String(Math.max(x,y)),String(Math.min(x,y))],`<b class="exa">${Math.max(x,y)}</b> is bigger than ${Math.min(x,y)}.`,'Compare the numbers.'])}}
 if(id==='maths-t2')for(let i=0;i<5;i++){const w=pickOne([10,10,20]),p=rint(1,w-1);mk(`${p} and <span class="qbl"></span> make ${w}`,w-p,`${p} + <b class="exa">${w-p}</b> = ${w}`,'Find the missing part.')}
 if(id==='maths-t3')add(1,10,6);if(id==='maths-t4')sub(5,20,6);if(id==='maths-t5')mul([2],6);
 if(id==='kg-maths-t2')for(let i=0;i<5;i++){const n=rint(2,18),more=Math.random()<.5;mk(`What is 1 ${more?'more':'less'} than ${n}?`,more?n+1:n-1,`1 ${more?'more':'less'} than ${n} is <b class="exa">${more?n+1:n-1}</b>.`,'Think one more or one less.')}
 if(id==='g2-maths-t1')for(let i=0;i<5;i++){const n=rint(101,999),h=Math.floor(n/100),t=Math.floor(n/10)%10;const ask=pickOne(['hundreds','tens']);mk(`How many ${ask} are in ${n}?`,ask==='hundreds'?h:t,`${n} has <b class="exa">${ask==='hundreds'?h:t}</b> ${ask}.`,'Place value.')}
 if(id==='g2-maths-t2'){add(10,60,3);sub(30,99,3)}
 if(id==='g2-maths-t3')mul([2,5,10],6);
 if(id==='g3-maths-t1'){mul([3,4,6],3);for(let i=0;i<3;i++){const t=pickOne([2,3,4,5]),y=rint(2,10);mk(`${t*y} ÷ ${t} = <span class="qbl"></span>`,y,`${t*y} ÷ ${t} = <b class="exa">${y}</b>`,'Divide.')}}
 if(id==='g3-maths-t2')for(let i=0;i<4;i++){const d=pickOne([2,4]),n=d*rint(2,6);mk(`What is ${d===2?'half':'a quarter'} of ${n}?`,n/d,`${n} ÷ ${d} = <b class="exa">${n/d}</b>`,'Share equally.')}
 if(id==='g3-maths-t3')for(let i=0;i<4;i++){const a=rint(12,40),b=rint(5,30);mk(`A bar is split into ${a} and ${b}. What is the whole?`,a+b,`${a} + ${b} = <b class="exa">${a+b}</b>`,'Part + part = whole.')}
 return g}
function extraQs(r){const s=SUB[r.sub],ur=!!s.rtl;const list=(XQ[r.id]||[]).concat(s.kind==='maths'?mathExtra(r.id):[]);
 return list.map(([q,o,exp,sub])=>mkQ(q,o,o[0],{sub:sub||(ur?'صحیح جواب چنیں۔':'Select the answer.'),exp,kind:'extra'})).filter(Boolean)}

