const ANIMALS=[['A baby dog is called a…',['puppy','kitten','calf','cub'],''],['A baby cow is called a…',['calf','foal','lamb','chick'],''],['A baby sheep is called a…',['lamb','kid','cub','duckling'],''],['A baby hen is called a…',['chick','calf','pup','foal'],''],['A baby horse is called a…',['foal','calf','kitten','lamb'],''],['A baby lion is called a…',['cub','pup','kid','chick'],''],['A baby goat is called a…',['kid','lamb','calf','foal'],''],['A baby duck is called a…',['duckling','chick','cygnet','gosling'],''],['Which animal has a trunk?',['elephant','giraffe','zebra','camel'],''],['Which animal has a very long neck?',['giraffe','elephant','hippo','bear'],''],['Which animal has black and white stripes?',['zebra','horse','cow','goat'],''],['Which animal can change colour?',['chameleon','rabbit','frog','owl'],''],['Which animal hops?',['kangaroo','snake','fish','cow'],''],['Which bird cannot fly?',['ostrich','crow','sparrow','eagle'],'']].map(([q,o])=>[q,o,`It is a <b class="exa">${o[0]}</b>.`]);
function mentalMaths(grade){const n=12,out=[];const R={nursery:[1,5],kg:[1,10],g1:[1,20],g2:[10,99],g3:[10,99]}[grade]||[1,20];
 for(let i=0;i<n;i++){const t=grade==='nursery'||grade==='kg'?pickOne(['+','+','after']):grade==='g1'?pickOne(['+','−','after','double']):pickOne(['+','−','×','÷','double','half']);
  let q,a,e;
  if(t==='+'){const x=rint(...R),y=rint(R[0],Math.max(R[0],Math.floor(R[1]/2)));q=`${x} + ${y}`;a=x+y}
  else if(t==='−'){const x=rint(...R),y=rint(0,x);q=`${x} − ${y}`;a=x-y}
  else if(t==='×'){const x=rint(2,grade==='g3'?10:5),y=rint(2,10);q=`${x} × ${y}`;a=x*y}
  else if(t==='÷'){const x=rint(2,5),y=rint(2,10);q=`${x*y} ÷ ${x}`;a=y}
  else if(t==='double'){const x=rint(1,grade==='g1'?10:50);q=`Double ${x}`;a=2*x}
  else if(t==='half'){const x=2*rint(2,25);q=`Half of ${x}`;a=x/2}
  else {const x=rint(...R);q=`What comes after ${x}`;a=x+1}
  out.push(mkQ(`${q} = <span class="qbl"></span>`.replace('What comes after','After').replace(/^(After \d+) =/,'$1 →'),[String(a),...near(a).map(String)],String(a),{sub:'Quick! Work it out in your head.',exp:`${q} = <b class="exa">${a}</b>`,kind:'mental'}))}
 return out.filter(Boolean)}
function bankQs(list){return shuffle(list).map(([q,o,exp])=>mkQ(q,o,o[0],{sub:'Select the answer.',exp,kind:'bank'})).filter(Boolean)}
const QONLY=[];
function regQuizOnly(){const add=(id,grade,kind,title,desc,gen)=>{const s=subjectsOf(grade).find(x=>x.kind===kind)||subjectsOf(grade)[0];if(!s)return;
  const r={id,sub:s.id,title,topic:title,en:'',pages:[],desc,obj:[],quizOnly:true,gen};QONLY.push(r);RID[id]=r};
 LIVE.forEach(g=>{add(`qx-mental-${g.id}`,g.id,'maths','Mental Maths Sprint','Quick sums in your head. New numbers every game.',()=>mentalMaths(g.id))});
 ['g1','g2','g3'].forEach(g=>add(`qx-pkgk-${g}`,g,g==='g1'?'social':'geography','Pakistan Quiz','Our flag, capital, national symbols and more.',()=>bankQs(PK_GK)));
 ['g1','g2','g3'].forEach(g=>add(`qx-spell-${g}`,g,'english','Spelling Bee','Pick the word that is spelled correctly.',()=>bankQs(SPELL)));
 ['nursery','kg','g1'].forEach(g=>add(`qx-animals-${g}`,g,g==='g1'?'science':'gk','Animal Fun','Baby animals and amazing animal facts.',()=>bankQs(ANIMALS)))}
